using System;
using System.Security.Cryptography;
using System.Text;

namespace Take_Leave.Services
{
    // Verifies signed SSO links generated by the parent learning portal.
    // The portal and this app share a secret key (SsoSettings:SharedSecret
    // in appsettings.json) that never travels over the network — only the
    // resulting signature does.
    public static class SsoTokenHelper
    {
        // Recomputes the expected signature for (email, ts) and compares it
        // to the one the portal sent. Returns true only if they match AND
        // the timestamp is within the allowed window (prevents replay of an
        // old captured link).
        public static bool VerifySignature(string email, long timestampUnixSeconds, string providedSignature, string sharedSecret, int maxAgeSeconds = 300)
        {
            if (string.IsNullOrWhiteSpace(email) || string.IsNullOrWhiteSpace(providedSignature) || string.IsNullOrWhiteSpace(sharedSecret))
            {
                return false;
            }

            long nowUnix = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            long age = Math.Abs(nowUnix - timestampUnixSeconds);
            if (age > maxAgeSeconds)
            {
                return false; // link expired or timestamp too far in the future
            }

            string expectedSignature = ComputeSignature(email, timestampUnixSeconds, sharedSecret);

            // Constant-time comparison to avoid timing attacks
            return CryptographicOperations.FixedTimeEquals(
                Encoding.UTF8.GetBytes(expectedSignature),
                Encoding.UTF8.GetBytes(providedSignature));
        }

        // Computes HMAC-SHA256("email|timestamp") using the shared secret,
        // then Base64Url-encodes it (URL-safe, no padding characters).
        public static string ComputeSignature(string email, long timestampUnixSeconds, string sharedSecret)
        {
            string normalizedEmail = email.Trim().ToLowerInvariant();
            string payload = $"{normalizedEmail}|{timestampUnixSeconds}";

            using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(sharedSecret));
            byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(payload));

            return Base64UrlEncode(hash);
        }

        private static string Base64UrlEncode(byte[] input)
        {
            return Convert.ToBase64String(input)
                .Replace('+', '-')
                .Replace('/', '_')
                .TrimEnd('=');
        }
    }
}